local terminal    = "ghostty"
local fileManager = "nautilus"
local menu        = "hyprlauncher"
local browser     = "zen-browser"
local noctalia = "noctalia"
local noctalia_ipc = noctalia .. " msg "

---------------------
--- GLOBAL STATES ---
---------------------

local MAX_ZOOM = 3.0
local MIN_ZOOM = 1.0
local is_zoomed = false
---------------------
---- HELPER FUNCTIONS ----
---------------------

local function set_zoom(offset)
    local current = hl.get_config("cursor.zoom_factor") or 1.0
    local new_zoom = 1.0

    if offset then
        new_zoom = math.min(MAX_ZOOM, math.max(MIN_ZOOM, current + offset))
    end

    is_zoomed = new_zoom > 1.0

    hl.config({ cursor = { zoom_factor = new_zoom } })
end

