--------------------------------------------------------------------------------
-- CONFIGURATION VARIABLES
--------------------------------------------------------------------------------

local global_speed = 6.0  -- Default 12.0
local speed_fast   = 4.0  -- Default 8.0
local speed_normal = 2.25 -- Default 5.0
local speed_out    = 1.75 -- Default 3.5 

local spring_cfg = {
  mass      = 0.51,  --Default 0.8
  stiffness = 250,  --Default 350
  dampening = 13 -- Default 30
}

--------------------------------------------------------------------------------
-- CURVE DEFINITIONS
--------------------------------------------------------------------------------

hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1} } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1} } })
hl.curve("linear",          { type = "bezier", points = { {0, 0},       {1, 1} } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1} } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1} } })

hl.curve("easy_fast", {
  type      = "spring",
  mass      = spring_cfg.mass,
  stiffness = spring_cfg.stiffness,
  dampening = spring_cfg.dampening
})

--------------------------------------------------------------------------------
-- ANIMATIONS CONFIGURATION
--------------------------------------------------------------------------------

hl.animation({ leaf = "global",        enabled = true,  speed = global_speed, bezier = "default" })

hl.animation({ leaf = "border",        enabled = true,  speed = speed_normal, bezier = "easeOutQuint" })
hl.animation({ leaf = "windows",       enabled = true,  speed = speed_fast,   spring = "easy_fast" })
hl.animation({ leaf = "windowsIn",     enabled = true,  speed = speed_fast,   spring = "easy_fast",   style = "popin 87%" })
hl.animation({ leaf = "windowsOut",    enabled = true,  speed = speed_out,    bezier = "quick",       style = "popin 87%" })
hl.animation({ leaf = "fadeIn",        enabled = true,  speed = speed_fast,   bezier = "almostLinear" })
hl.animation({ leaf = "fadeOut",       enabled = true,  speed = speed_out,    bezier = "almostLinear" })
hl.animation({ leaf = "fade",          enabled = true,  speed = speed_fast,   bezier = "quick" })
hl.animation({ leaf = "layers",        enabled = true,  speed = speed_normal, bezier = "easeOutQuint" })
hl.animation({ leaf = "layersIn",      enabled = true,  speed = speed_normal, bezier = "easeOutQuint", style = "fade" })
hl.animation({ leaf = "layersOut",     enabled = true,  speed = speed_out,    bezier = "linear",       style = "fade" })
hl.animation({ leaf = "fadeLayersIn",  enabled = true,  speed = speed_normal, bezier = "almostLinear" })
hl.animation({ leaf = "fadeLayersOut", enabled = true,  speed = speed_out,    bezier = "almostLinear" })
hl.animation({ leaf = "workspaces",    enabled = true,  speed = speed_fast,   bezier = "quick",        style = "fade" })
hl.animation({ leaf = "workspacesIn",  enabled = true,  speed = speed_fast,   bezier = "quick",        style = "fade" })
hl.animation({ leaf = "workspacesOut", enabled = true,  speed = speed_out,    bezier = "quick",        style = "fade" })
hl.animation({ leaf = "zoomFactor",    enabled = true,  speed = global_speed, bezier = "quick" })

